styles:
.mo-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      align-items: stretch;
    }
    @media (max-width: 900px) {
      .mo-grid { grid-template-columns: 1fr; }
    }
    .mo-panel {
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg);
      padding: 0.85rem;
      min-height: 0;
    }
    .mo-panel__title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.5rem;
      font-size: 0.72rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      color: var(--is-text-dim);
      margin-bottom: 0.65rem;
    }
    .mo-target {
      padding: 1rem;
      background: var(--is-control-bg);
      border-radius: var(--is-radius-sm);
      border: 1px solid var(--is-border-soft);
      color: var(--is-text);
      min-height: 3rem;
      line-height: 1.5;
    }
    .mo-target [data-chip] {
      display: inline-block;
      margin-left: 0.35em;
      padding: 0.1em 0.45em;
      border-radius: 999px;
      background: var(--is-brand-soft);
      color: var(--is-brand-text);
      font-size: 0.8em;
    }
    .mo-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-top: 0.75rem;
    }
    .mo-hint {
      margin-top: 0.75rem;
      font-size: 0.85rem;
      color: var(--is-text-soft);
      line-height: 1.45;
    }
    .mo-hint code { font-size: 0.9em; }
    .mo-live {
      margin: 0 !important;
      max-height: 220px;
      overflow: auto;
      font-size: 0.78rem !important;
    }
    .mo-uses {
      display: grid;
      gap: 0.65rem;
      margin: 0 0 1rem;
      padding: 0;
      list-style: none;
    }
    .mo-uses li {
      display: grid;
      grid-template-columns: 1.5rem 1fr;
      gap: 0.55rem;
      align-items: start;
      color: var(--is-text-soft);
      font-size: 0.92rem;
      line-height: 1.45;
    }
    .mo-uses is-icon {
      width: 1.15em;
      height: 1.15em;
      color: var(--is-accent);
      margin-top: 0.15em;
    }
    .log .type-child { color: #69db7c; }
    .log .type-attr { color: #ffe066; }
    .log .type-text { color: #74c0fc; }
